  select md5('democ:m:lehigh-premier-autos:0')::uuid, b, (select id from users where phone = '+15705559601'), 'owner', 'Francisco Ortiz', null, '{"es":"Dueño y gerente de ventas","en":"Owner and sales manager"}'::jsonb, 'https://images.pexels.com/photos/1681010/pexels-photo-1681010.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Aquí no hay sorpresas: el precio, los impuestos, las placas y el cargo del dealer, todo por escrito. Y tu mecánico puede revisar el carro antes de firmar.","en":"No surprises here: the price, taxes, tags and dealer fee, all in writing. And your mechanic can check the car before you sign."}'::jsonb, '{all}'::text[], 'active', true, 0, 2012, true, true
