  insert into items (business_id, module, section_id, name, descr, price_cents, unit, tax_pct, photos, channels, stock_mode, stock_left, stock_par, duration_min, price_from, svc_opts, svc_kind, svc_attrs, deposit_cents, attrs, featured, sort, tags) values (b, 'svc', s, '{"es":"Tasación de tu carro (trade-in)","en":"Trade-in appraisal"}'::jsonb, '{"es":"Gratis y por escrito. Te decimos cuánto vale antes de que decidas.","en":"Free and in writing. We tell you what it is worth before you decide."}'::jsonb, 0, 'u', 6, array['https://images.pexels.com/photos/1638459/pexels-photo-1638459.jpeg?auto=compress&cs=tinysrgb&h=600']::text[], array['dlv','pick']::text[], 'none', 0, 10, 30, false, '[]'::jsonb, null, '{}'::jsonb, 0, '{}'::jsonb, false, 0, '{}'::text[]);
