  select md5('democ:m:carros-a-plazos-wilkes-barre:3')::uuid, b, null, 'staff', 'Jorge Núñez', null, '{"es":"Mecánico del lote","en":"Lot mechanic"}'::jsonb, 'https://images.pexels.com/photos/16160952/pexels-photo-16160952.jpeg?auto=compress&cs=tinysrgb&w=160', array['es']::text[], '[]'::jsonb, null, '{}'::text[], 'active', true, 3, 2021, true, false
