  select md5('democ:m:auto-plazos-scranton:0')::uuid, b, (select id from users where phone = '+15705559633'), 'owner', 'Edwin Reyes', null, '{"es":"Dueño y gerente de ventas","en":"Owner and sales manager"}'::jsonb, 'https://images.pexels.com/photos/16160952/pexels-photo-16160952.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Llegué a Pennsylvania en 2003 y compré mi primer carro con ITIN. Por eso sé lo que se siente y ayudo a otros a hacerlo bien.","en":"I came to Pennsylvania in 2003 and bought my first car with an ITIN. That is why I know how it feels and help others do it right."}'::jsonb, '{all}'::text[], 'active', true, 0, 2010, true, true
