  values (b, 'hzl', 'NEG-DEALER', array['NEG-DEALER-04','NEG-DEALER-02']::text[], 'Carros Fáciles Hazleton', 'active', 'self', (select id from users where phone = '+15705559636'), 'local', '630 N Laurel St, Hazleton PA', st_geogfromtext('POINT(-75.969204 40.967725)'), false, null, '+15705550152', true, array['es','en']::text[], '{"es":"Carros con plan semanal, sin necesidad de crédito en Hazleton desde 2008. El enganche, el pago a la semana y el total que pagas van por escrito en cada carro. Hablamos español e inglés.","en":"Cars with a weekly payment plan, no credit required in Hazleton since 2008. The down payment, the weekly payment and the total you pay are in writing on every car. We speak Spanish and English."}'::jsonb, 2008, array['acepta-tarjeta','estacionamiento','sala-de-espera','financiamiento']::text[], array['sincredito','enganche','prueba','esp','y10']::text[], '{local}', '{"m":"shop","eng":100000,"autos_der":["eta","fee"],"tarjeta":{"eta":{"es":"11 carros en el lote","en":"11 cars on the lot"},"fee":{"es":"Sin crédito · el total que pagas, por escrito en cada carro","en":"No credit · the total you pay, in writing on every car"}}}'::jsonb, 'data:image/svg+xml;utf8,%3Csvg%20xmlns%3D''http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg''%20viewBox%3D''0%200%20120%20120''%3E%3Crect%20width%3D''120''%20height%3D''120''%20rx%3D''26''%20fill%3D''%230F4C5C''%2F%3E%3Ctext%20x%3D''60''%20y%3D''76''%20font-family%3D''Arial%2CHelvetica%2Csans-serif''%20font-size%3D''46''%20font-weight%3D''700''%20fill%3D''%23F6E7B0''%20text-anchor%3D''middle''%3ECF%3C%2Ftext%3E%3C%2Fsvg%3E', array['svc','staff','nov']::text[], 'emp', true);
  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'month', 1499, '2008-05-20'::date, '2008-05-20'::date + 30, 'card', now() + interval '25 days', '2008-05-20'::date) on conflict (business_id) do nothing;
insert into business_hours (business_id, weekday, open, ranges) values (b, 0, false, '[]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 1, true, '[["09:00","19:00"]]'::jsonb);
insert into business_hours (business_id, weekday, open, ranges) values (b, 2, true, '[["09:00","19:00"]]'::jsonb);
