  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:0')::uuid, 'business', b, '395537', 'Pexels', 0) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:1')::uuid, 'business', b, '35627388', 'Pexels', 1) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:2')::uuid, 'business', b, '12700837', 'Pexels', 2) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:3')::uuid, 'business', b, '35627355', 'Pexels', 3) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:4')::uuid, 'business', b, '5076489', 'Pexels', 4) on conflict (id) do nothing;
  insert into media (id, owner_kind, owner_id, url, credit, sort) values (md5('democ:img:carros-faciles-hazleton:5')::uuid, 'business', b, '35627348', 'Pexels', 5) on conflict (id) do nothing;
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:carros-faciles-hazleton:0')::uuid, b, (select id from users where phone = '+15705559636'), 'owner', 'Marisol Soto', null, '{"es":"Dueño y gerente de ventas","en":"Owner and sales manager"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Llegué a Pennsylvania en 2003 y compré mi primer carro con ITIN. Por eso sé lo que se siente y ayudo a otros a hacerlo bien.","en":"I came to Pennsylvania in 2003 and bought my first car with an ITIN. That is why I know how it feels and help others do it right."}'::jsonb, '{all}'::text[], 'active', true, 0, 2008, true, true
  where not exists (select 1 from business_members x where x.id = md5('democ:m:carros-faciles-hazleton:0')::uuid);
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:carros-faciles-hazleton:1')::uuid, b, null, 'staff', 'Víctor Rodríguez', null, '{"es":"Asesor de ventas","en":"Sales advisor"}'::jsonb, 'https://images.pexels.com/photos/20045343/pexels-photo-20045343.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, null, '{}'::text[], 'active', true, 1, 2010, true, true
  where not exists (select 1 from business_members x where x.id = md5('democ:m:carros-faciles-hazleton:1')::uuid);
  insert into business_members (id, business_id, user_id, kind, display_name, nickname, role, photo_url, languages, specialties, bio, panel_access, status, show_on_page, sort, since_year, same_as_business_hours, takes_bookings)
  select md5('democ:m:carros-faciles-hazleton:2')::uuid, b, null, 'staff', 'Carolina Batista', null, '{"es":"Cobros y papeles","en":"Payments and paperwork"}'::jsonb, 'https://images.pexels.com/photos/29881401/pexels-photo-29881401.jpeg?auto=compress&cs=tinysrgb&w=160', array['es']::text[], '[]'::jsonb, null, '{}'::text[], 'active', true, 2, 2020, true, false
  where not exists (select 1 from business_members x where x.id = md5('democ:m:carros-faciles-hazleton:2')::uuid);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿El precio incluye impuestos y placas?","en":"Does the price include taxes and tags?"}'::jsonb, '{"es":"No: el precio es antes de impuestos. En cada carro verás el total en la puerta: precio + impuesto de PA (6 %) + placas y título ($150) + cargo del dealer ($349).","en":"No: the price is before taxes. On each car you will see the out-the-door total: price + PA tax (6%) + tags and title ($150) + dealer fee ($349)."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cuál es el cargo del dealer?","en":"What is the dealer fee?"}'::jsonb, '{"es":"$349, por debajo del tope que fija Pennsylvania. Siempre está en el total en la puerta, antes de firmar.","en":"$349, below the cap set by Pennsylvania. It is always in the out-the-door total, before you sign."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo funciona el plan semanal?","en":"How does the weekly plan work?"}'::jsonb, '{"es":"Das un enganche (desde $1,000) y pagas a la semana por 24 meses. El total que pagas al final, con la tasa que resulta, va por escrito en cada carro antes de firmar.","en":"You pay a down payment (from $1,000) and pay weekly for 24 months. The total you end up paying, with the resulting rate, is in writing on each car before you sign."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo llevar el carro a mi mecánico antes de comprar?","en":"Can I take the car to my mechanic before buying?"}'::jsonb, '{"es":"Sí, siempre. Nos dices cuándo y lo preparamos. Si algo sale en la revisión, lo hablamos antes de firmar.","en":"Yes, always. Tell us when and we get it ready. If anything comes up in the check, we talk about it before you sign."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Aceptan mi carro como parte de pago?","en":"Do you take my car as a trade-in?"}'::jsonb, '{"es":"Por ahora no recibimos carros como parte de pago; si quieres vender el tuyo, te decimos a quién preguntar.","en":"We do not take trade-ins right now; if you want to sell yours, we will point you to who to ask."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo pido una prueba de manejo?","en":"How do I book a test drive?"}'::jsonb, '{"es":"En la ficha de cada carro eliges una hora libre y nos llega al instante. Antes de la prueba no se cobra nada.","en":"On each car you pick a free time and it reaches us instantly. Nothing is charged before the test drive."}'::jsonb, 5);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué pasa con el título?","en":"What about the title?"}'::jsonb, '{"es":"Cada carro dice si el título es limpio, reconstruido o salvage. Un salvage no se maneja en la calle hasta pasar la inspección de PA.","en":"Each car says whether the title is clean, rebuilt or salvage. A salvage car cannot be driven on the street until it passes PA inspection."}'::jsonb, 6);
