  insert into business_stats_cache (business_id, plan, verified, photo_count) values (b, 'pro', true, 6) on conflict (business_id) do update set plan = 'pro', verified = true, photo_count = excluded.photo_count, updated_at = now();
  insert into subscriptions (business_id, status, cycle, price_cents, trial_started_at, trial_ends_at, trial_choice, current_period_end, created_at) values (b, 'active', 'year', 14990, '2018-03-05'::date, '2018-03-05'::date + 30, 'card', now() + interval '10 days', '2018-03-05'::date) on conflict (business_id) do nothing;
