  select md5('democ:m:autos-sin-credito-hazleton:0')::uuid, b, (select id from users where phone = '+15705559641'), 'owner', 'Ramón Soto', null, '{"es":"Dueño y gerente de ventas","en":"Owner and sales manager"}'::jsonb, 'https://images.pexels.com/photos/11579595/pexels-photo-11579595.jpeg?auto=compress&cs=tinysrgb&w=160', array['es','en']::text[], '[]'::jsonb, '{"es":"Empecé vendiendo un carro a la vez en 2018. Hoy sigo explicando el total en la puerta antes de que firmes, línea por línea.","en":"I started selling one car at a time in 2018. Today I still explain the out-the-door total before you sign, line by line."}'::jsonb, '{all}'::text[], 'active', true, 0, 2018, true, true
