  where not exists (select 1 from business_members x where x.id = md5('democ:m:autos-aprobados-allentown:2')::uuid);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿El precio incluye impuestos y placas?","en":"Does the price include taxes and tags?"}'::jsonb, '{"es":"No: el precio es antes de impuestos. En cada carro verás el total en la puerta: precio + impuesto de PA (6 %) + placas y título ($165) + cargo del dealer ($199).","en":"No: the price is before taxes. On each car you will see the out-the-door total: price + PA tax (6%) + tags and title ($165) + dealer fee ($199)."}'::jsonb, 0);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cuál es el cargo del dealer?","en":"What is the dealer fee?"}'::jsonb, '{"es":"$199, por debajo del tope que fija Pennsylvania. Siempre está en el total en la puerta, antes de firmar.","en":"$199, below the cap set by Pennsylvania. It is always in the out-the-door total, before you sign."}'::jsonb, 1);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo funciona el plan semanal?","en":"How does the weekly plan work?"}'::jsonb, '{"es":"Das un enganche (desde $1,000) y pagas a la semana por 36 meses. El total que pagas al final, con la tasa que resulta, va por escrito en cada carro antes de firmar.","en":"You pay a down payment (from $1,000) and pay weekly for 36 months. The total you end up paying, with the resulting rate, is in writing on each car before you sign."}'::jsonb, 2);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Puedo llevar el carro a mi mecánico antes de comprar?","en":"Can I take the car to my mechanic before buying?"}'::jsonb, '{"es":"Sí, siempre. Nos dices cuándo y lo preparamos. Si algo sale en la revisión, lo hablamos antes de firmar.","en":"Yes, always. Tell us when and we get it ready. If anything comes up in the check, we talk about it before you sign."}'::jsonb, 3);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Aceptan mi carro como parte de pago?","en":"Do you take my car as a trade-in?"}'::jsonb, '{"es":"Por ahora no recibimos carros como parte de pago; si quieres vender el tuyo, te decimos a quién preguntar.","en":"We do not take trade-ins right now; if you want to sell yours, we will point you to who to ask."}'::jsonb, 4);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Cómo pido una prueba de manejo?","en":"How do I book a test drive?"}'::jsonb, '{"es":"En la ficha de cada carro eliges una hora libre y nos llega al instante. Antes de la prueba no se cobra nada.","en":"On each car you pick a free time and it reaches us instantly. Nothing is charged before the test drive."}'::jsonb, 5);
  insert into faqs (business_id, question, answer, sort) values (b, '{"es":"¿Qué pasa con el título?","en":"What about the title?"}'::jsonb, '{"es":"Cada carro dice si el título es limpio, reconstruido o salvage. Un salvage no se maneja en la calle hasta pasar la inspección de PA.","en":"Each car says whether the title is clean, rebuilt or salvage. A salvage car cannot be driven on the street until it passes PA inspection."}'::jsonb, 6);
  if (select coalesce((value #>> '{}')::int, 0) from platform_config where key = 'dealer_doc_fee_cap_cents') < 19900 or (select parts_bp from tax_rules where city_id = 'alw' and category_id = 'NEG-DEALER' and effective_from <= now() order by effective_from desc, id desc limit 1) is distinct from 600 then raise exception 'el tope de PA o el impuesto de la ciudad no son los que usa esta semilla'; end if;
