  from businesses b cross join lateral unnest(array['pa_dealer','pa_vendedor_autos','pa_venta_plazos']::text[]) with ordinality o(k, n) join license_kinds k on k.key = o.k
 where b.id = 'carros-faciles-hazleton' and not exists (select 1 from licenses l where l.business_id = b.id and l.kind = k.key);
