  from (values
('cumbre-motors', 'hzl', '+15705558500', 'D-3300001', 'cita', 4, 'All good overall. The test drive started a few minutes late but they let me know. The paperwork took longer than I thought, though everything was clear. Recommended.', 'en', '{"trato":1,"puertaOk":1,"tituloOk":1,"fotosOk":1,"aTiempo":"a","sinPresion":1}', '{"dia":"2010-07-24","que":"prueba","tot":2323300}', 'We appreciate it, Mariela. That is the service we always want to give.', -5952, 495, 'en', -5955, 625),
