insert into review_helpful (review_id, user_id)
select r.id, h.id from reviews r cross join lateral (select u.id from _c_u u where u.id <> r.user_id order by md5(r.id::text || u.phone) limit (r.id % 5)::int) h
 where r.business_id = any(array['cumbre-motors','lehigh-premier-autos','valle-del-susquehanna-autos','lackawanna-auto-plaza','berks-nuevos-y-certificados','montana-motors','autos-nuevos-del-valle','wyoming-auto-group','keystone-premier-motors','schuylkill-auto-mall','autos-usados-don-chino','lote-la-estrella-allentown','autos-selectos-wilkes-barre','autos-usados-el-primo','lote-reading-latino','autos-garantizados-hazleton','lehigh-valley-used-cars','autos-buen-precio-wyoming','lote-scranton-selecto','autos-usados-los-compadres','lote-independiente-don-pedro','independiente-auto-sales-allentown','lote-el-cibaeno-wilkes-barre','lote-independiente-cerro-alto','lote-berks-auto','autos-independientes-hazleton','lote-los-hermanos-allentown','lote-la-montana-wyoming','independiente-motors-scranton','lote-santa-maria-reading','compre-aqui-pague-aqui-allentown','pague-aqui-su-carro-hazleton','carros-a-plazos-wilkes-barre','auto-plazos-scranton','compre-aqui-reading','carros-faciles-hazleton','pague-semanal-autos-allentown','auto-credito-casa-wyoming','carros-a-su-medida-scranton','plan-semanal-autos-reading','autos-sin-credito-hazleton','sin-credito-autos-allentown','tu-carro-sin-credito-wilkes-barre','autos-sin-credito-scranton','sin-credito-reading-autos','carro-sin-historial-hazleton','autos-aprobados-allentown','sin-credito-wyoming-motors','carros-sin-credito-scranton','autos-sin-banco-reading']::text[]) and not exists (select 1 from review_helpful x where x.review_id = r.id) on conflict do nothing;
